<div class="c-modal lg fc-delib-preview-popup" id="fc-deliberation-preview-modal" role="dialog" aria-modal="true" hidden><button type="button" class="c-modal-backdrop" data-fc-preview-close></button><div class="c-modal-panel"><div class="c-modal-head"><h2 class="c-modal-title">미리보기</h2><button type="button" class="c-modal-close" data-fc-preview-close>닫기</button></div><div class="c-modal-body"><div class="fc-delib-preview-inner detail-page" data-fc-preview-content></div></div><div class="c-modal-foot"><div class="c-modal-btns"><button type="button" class="btn btn-sub" data-fc-preview-capture>화면캡쳐</button><button type="button" class="btn btn-primary" data-fc-preview-pdf>PDF 다운받기</button></div></div></div></div>
<div class="c-modal sm" id="fc-deliberation-required-modal" role="dialog" aria-modal="true" hidden><button type="button" class="c-modal-backdrop" data-fc-required-close></button><div class="c-modal-panel"><button type="button" class="c-modal-close" data-fc-required-close>닫기</button><div class="c-modal-body"><p class="modal-text"><strong>심의필 정보 등록 후<br>심의 요청용 화면을 미리볼 수 있습니다.</strong></p></div><div class="c-modal-foot"><a class="btn btn-primary" href="<?= base_url('mypage/fcreviewed') ?>">심의필 정보 관리 바로가기</a></div></div></div>
<script>window.MyFCDeliberationPreview=(function(){const p=document.getElementById('fc-deliberation-preview-modal'),r=document.getElementById('fc-deliberation-required-modal'),closeOthers=m=>document.querySelectorAll('.c-modal.is-open').forEach(x=>{if(x!==m){x.classList.remove('is-open');x.hidden=true}}),o=m=>{closeOthers(m);m.hidden=false;m.classList.add('is-open');document.body.classList.add('popup-open')},c=m=>{m.classList.remove('is-open');m.hidden=true;if(!document.querySelector('.c-modal.is-open'))document.body.classList.remove('popup-open')};p.querySelectorAll('[data-fc-preview-close]').forEach(b=>b.onclick=()=>c(p));r.querySelectorAll('[data-fc-required-close]').forEach(b=>b.onclick=()=>c(r));document.addEventListener('click',e=>{const b=e.target.closest('[data-fc-deliberation-preview]');if(!b)return;e.preventDefault();fetch('<?= base_url('mypage/fc-deliberation-preview') ?>').then(x=>x.json()).then(x=>{if(x.status==='required')return o(r);if(x.status!=='success')return alert(x.message||'미리보기를 불러오지 못했습니다.');p.querySelector('[data-fc-preview-content]').innerHTML=x.html;o(p)}).catch(()=>alert('미리보기를 불러오지 못했습니다.'))});return{}})();</script>
<script src="https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js"></script><script>(function(){const target=()=>document.querySelector('[data-fc-preview-content]');async function canvas(){if(!window.html2canvas)throw new Error();return html2canvas(target(),{scale:2,useCORS:true,backgroundColor:'#ffffff'});}document.querySelector('[data-fc-preview-capture]').onclick=async()=>{try{const c=await canvas(),a=document.createElement('a');a.download='myfc-deliberation-preview.png';a.href=c.toDataURL('image/png');a.click()}catch(e){alert('화면캡쳐를 준비하지 못했습니다.')}};document.querySelector('[data-fc-preview-pdf]').onclick=async()=>{try{const c=await canvas(),pdf=new window.jspdf.jsPDF('p','mm','a4'),w=190,h=c.height*w/c.width;pdf.addImage(c.toDataURL('image/png'),'PNG',10,10,w,h);pdf.save('myfc-deliberation-preview.pdf')}catch(e){alert('PDF를 준비하지 못했습니다.')}}})();</script>
